"""Original interview bank, authored for Offer Quest. Run to regenerate JSON + SQL seed."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
questions = []
def add(category, rows):
    prefix = {'ML':'ml','AI/LLM':'ai','Python':'py','BQ':'bq'}[category]
    for i, row in enumerate(rows, 1):
        prompt, points = row
        questions.append(dict(id=f'{prefix}-{i:02}', category=category, difficulty='Hard' if i%4==0 else 'Medium', prompt=prompt, rubric=points.split('|')))
